package com.bank.product.security;
import com.bank.product.dto.FirstSubmissionErrorResponse; import com.fasterxml.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.http.MediaType; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import java.util.*;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig {private final JwtAuthenticationFilter jwt; private final ObjectMapper json;
 @Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(org.springframework.http.HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/actuator/health/**","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((req,res,x)->{res.setStatus(401);res.setContentType(MediaType.APPLICATION_JSON_VALUE);json.writeValue(res.getOutputStream(),new FirstSubmissionErrorResponse("UNAUTHORIZED","Authentication required or token invalid",List.of(),UUID.randomUUID().toString()));}).accessDeniedHandler((req,res,x)->{res.setStatus(403);res.setContentType(MediaType.APPLICATION_JSON_VALUE);json.writeValue(res.getOutputStream(),new FirstSubmissionErrorResponse("FORBIDDEN","Insufficient role",List.of(),UUID.randomUUID().toString()));})).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
